import requests

class News:
    def __init__(self, company_name, news_api_key):
        self.news_params = {
            'q': company_name,
            'language': 'en',
            'apiKey': news_api_key
        }
    
    def get_data(self): 
        news_res = requests.get(url='https://newsapi.org/v2/everything', params=self.news_params)
        news_data = news_res.json()
        news_articles = news_data['articles']
        return news_articles


